local context = require "wa.context"
local events = require "wa.events"
local variables = require "wa.variables"

local R = require "core.lib.rathena"
local RESRVPTS = variables.character_integer "resrvpts"

return function()
  local npc = context:get_instance()
  events.on("click", function(player, conversation)
    R.run(function()
      conversation:show_image("kafra_05", "right")
      conversation:say("[Kafra Leilah]", "Hm...?", "Oh, welcome to", "the Kafra Corporation", "Headquarters. Did you", "need something?")
      conversation:wait_for_next()
      do
        local value_1 = conversation:choose("Save", "Use Storage", "Rent a Pushcart", "Cancel")
        if value_1 == 1 then goto case_3
        elseif value_1 == 2 then goto case_4
        elseif value_1 == 3 then goto case_5
        elseif value_1 == 4 then goto case_6
        end
        goto switch_end_2
        ::case_3::
        conversation:say("[Kafra Leilah]", "Your Respawn Point has", "been saved here, inside", "of the Kafra Corporation", "Headquarters. Thank you.")
        conversation:wait_for_next()
        player:set_save_point("aldeba_in", 96, 179)
        conversation:say("[Kafra Leilah]", "Please make use of", "the Kafra Services that are", "available throughout all of", "Midgard. Thank you for", "visiting the Kafra Headquarters.")
        conversation:close()
        goto switch_end_2
        ::case_4::
        if (player.zeny < 20) then
          conversation:say("[Kafra Leilah]", "Excuse me, but it", "seems that you don't", "have the 20 zeny to pay", "the Storage access fee...")
          conversation:hide_image()
          do return end
        end
        conversation:say("[Kafra Leilah]", "Although this facility is", "exclusively intended for", "the training of Kafra Employee", "and administrative functions,", "I'll access your Storage for you.")
        conversation:wait_for_next()
        player:pay_zeny(20)
        RESRVPTS:set(player, (RESRVPTS:get(player) + 4))
        conversation:say("[Kafra Leilah]", "In the future, please", "ask the Kafra Employee on", "duty if you wish to use", "any of the Kafra Services.", "Thank you for your patronage.")
        require("core.functions.F_CheckKafCode")(player, conversation, npc)
        conversation:close()
        R.not_available(conversation, "Storage")
        goto switch_end_2
        ::case_5::
        conversation:say("[Kafra Leilah]", "My apologies, but I'm", "not on duty. I'd assist you", "if I could, but actually don't", "have any available Pushcarts.", "Why don't you ask another Kafra", "Employee for assistance?")
        conversation:wait_for_next()
        conversation:say("[Kafra Leilah]", "Kafra Employees are", "stationed all over the", "Midgard continent,", "and you should be able to find", "plenty outside in Al De Baran.")
        conversation:close()
        goto switch_end_2
        ::case_6::
        conversation:say("[Kafra Leilah]", "^666666*Whew...*^000000", "Great, because I'm", "actually on my break", "right now. Choosing", "''Cancel'' was a good", "move on your part.")
        conversation:close()
        goto switch_end_2
        ::switch_end_2::
      end
      conversation:hide_image()
      do return end
    end)
  end)
end
